 "content": "def transform(grid):
    """Overlay translated copies of the distinctive nonzero stencil, recoloring matching zeros."""
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r-r0, c-c0) for r, c in points]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = 8
    return out
